#!/usr/bin/env python3
"""Regenera el sitio estático a partir de data/caballos.json. No requiere paquetes."""
from pathlib import Path
import json, html, re, sys

ROOT = Path(__file__).resolve().parents[1]
HORSES = json.loads((ROOT/'data/caballos.json').read_text(encoding='utf-8'))
BRAND = 'COWBOY Polo Horses'
SITE_URL = 'https://ejemplo-cowboy.vercel.app'  # CAMBIAR por el dominio real antes de publicar

def esc(x): return html.escape(str(x),quote=True)
def imgurl(pid, w=1000): return f'https://images.pexels.com/photos/{pid}/pexels-photo-{pid}.jpeg?auto=compress&amp;cs=tinysrgb&amp;w={w}'
def fallback(prefix): return prefix + 'assets/images/horse-placeholder.svg'
def img(pid, alt, prefix='', klass='', eager=False, width=1000):
    return f'<img class="{klass}" src="{imgurl(pid,width)}" alt="{esc(alt)}" data-fallback="{fallback(prefix)}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=\"high\"" if eager else ""}>'

def logo(prefix=''):
    return f'''<a class="brand" href="{prefix}index.html" aria-label="COWBOY Polo Horses, inicio">
       <span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 50 60" width="43" height="51" fill="none"><path d="M12 51L17 38L12 29L20 18L20 7L27 11L34 5L36 21L42 28L37 36L39 50L29 53L20 48L12 51Z" stroke="currentColor" stroke-width="1.45" stroke-linejoin="round"/><path d="M20 18L30 20L36 28L24 33L17 38M28 27L29 27M20 48L26 39L37 36" stroke="currentColor" stroke-width="1.35" stroke-linejoin="round"/><path d="M12 55H41" stroke="currentColor" stroke-width="1.4"/></svg></span>
       <span class="brand-word"><strong>COWBOY<span class="brand-dot">.</span></strong><small>POLO HORSES</small></span></a>'''

