    return '''<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20.5 11.7a8.5 8.5 0 0 1-12.3 7.7L3.5 20.5l1.3-4.4A8.5 8.5 0 1 1 20.5 11.7Z"/><path d="M9 8.5c.3-.4.6-.4.9-.4.3 0 .6.1.8.6l.8 1.7c.2.4-.1.8-.5 1.2-.3.3-.2.5 0 .8.6.9 1.4 1.7 2.3 2.2.3.2.5.3.8 0l.8-.8c.4-.3.7-.3 1.1-.1l1.8.8c.5.3.5.6.4.9-.1.8-.9 1.6-1.8 1.7-1.2.1-3.1-.8-4.8-2.4-1.8-1.7-2.9-3.7-2.9-4.8 0-.6.1-1 .3-1.4Z"/></svg>'''
